eo":{"title":"Fjärås Sand & Makadam – grus, makadam, sand och jord i Kungsbacka","description":"Grus, makadam, sand, jord, bark och sten från egen täkt i Fjärås. Leverans med egna lastbilar och kranbil. Familjeföretag sedan 1961."},"sections":{"order":["hero","aret-runt","tjanster","en-kontakt","kunder","om-oss","process","faq","kontakt","karta"],"items":{"hero":{"type":"hero","hidden":false,"anchor":"","label":"","eyebrow":"Familjeföretag i Fjärås sedan 1961","heading":"Grus, sand och makadam från egen täkt","image":{"src":"/photos/site/paddock-2000.webp","variants":[{"width":480,"src":"/photos/site/paddock-480.webp"},{"width":800,"src":"/photos/site/paddock-800.webp"},{"width":1200,"src":"/photos/site/paddock-1200.webp"},{"width":1600,"src":"/photos/site/paddock-1600.webp"},{"width":2000,"src":"/photos/site/paddock-2000.webp"}],"alt":"Lastbil från Fjärås Sand & Makadam vid en paddock","focus":"72% 50%"},"button":{"label":"Begär offert","href":"#offert"},"layout":"split"},"tjanster":{"type":"services","hidden":false,"anchor":"tjanster","label":"","heading":"Våra tjänster","link":{"label":"Begär offert","href":"#offert"},"cardLinkPrefix":"Läs mer om"},"aret-runt":{"type":"uppdragCarousel","hidden":false,"anchor":"","label":"","heading":"Våra produkter","text":"Kross, makadam, grus, sand, sten, jord och bark – i olika fraktioner, i bil eller storsäck. Välj en produkt för bilder och mer information.","link":{"label":"Alla produkter och priser","href":"/produkter"}},"en-kontakt":{"type":"feature","hidden":false,"anchor":"","label":"","heading":"Egen täkt och egna lastbilar","text":"Vi krossar och säljer grus, makadam och jordprodukter från vår egen täkt och levererar med egna lastbilar och kranbil. Vi har jobbat i branschen i över 60 år.","image":{"src":"/photos/site/20120801-161748-700.webp","variants":[{"width":480,"src":"/photos/site/20120801-161748-480.webp"},{"width":700,"src":"/photos/site/20120801-161748-700.webp"}],"alt":"Täkten i Fjärås med krossverk och lastbilar"},"cards":{"order":["dimensioner","byggsats"],"items":{"dimensioner":{"heading":"Rätt material på rätt plats","text":"Vi vet vilket material som passar bäst för gången, uppfarten, dräneringen eller paddocken – fråga oss gärna.","icon":"Mountain","link":{"label":"Se produkterna","href":"/produkter"},"image":{"src":"/photos/site/makadam-medium-vatt-700.webp","variants":[{"width":480,"src":"/photos/site/makadam-medium-vatt-480.webp"},{"width":700,"src":"/photos/site/makadam-medium-vatt-700.webp"}],"alt":"Makadam"}},"byggsats":{"heading":"Kranbil och storsäck","text":"Material i storsäck på ca 1 500 kg, lyft på plats med kranbil som når upp till 15 meter.","icon":"Truck","link":{"label":"Om storsäckar","href":"/tjanster/storsackar"},"image":{"src":"/photos/site/storsack-kranbil-2000.webp","variants":[{"width":480,"src":"/photos/site/storsack-kranbil-480.webp"},{"width":800,"src":"/photos/site/storsack-kranbil-800.webp"},{"width":1200,"src":"/photos/site/storsack-kranbil-1200.webp"},{"width":1600,"src":"/photos/site/storsack-kranbil-1600.webp"},{"width":2000,"src":"/photos/site/storsack-kranbil-2000.webp"}],"alt":"Kranbil som lyfter en storsäck"}}}}},"kunder":{"type":"promo","hidden":false,"anchor":"","label":"","boxes":{"order":["bastu","attefall"],"items":{"bastu":{"side":"left","heading":"Paddockar och paddocksand","text":"Stenmjöl 0–2 mm från egen täkt – populärt i hästbranschen och omtyckt av våra kunder.","link":{"label":"Om paddockar","href":"/tjanster/paddockar"},"image":{"src":"/photos/site/paddock2-960.webp","variants":[{"width":480,"src":"/photos/site/paddock2-480.webp"},{"width":800,"src":"/photos/site/paddock2-800.webp"},{"width":960,"src":"/photos/site/paddock2-960.webp"}],"alt":"Lastbil som tippar material till en paddock"}},"attefall":{"side":"right","heading":"Grusvägar som håller","text":"Grusspridning, väghyvling och dammbindning för privatpersoner, vägföreningar och skogsvägar.","link":{"label":"Om grusspridning","href":"/tjanster/grusspridning"},"image":{"src":"/photos/site/vaghyvel-2000.webp","variants":[{"width":480,"src":"/photos/site/vaghyvel-480.webp"},{"width":800,"src":"/photos/site/vaghyvel-800.webp"},{"width":1200,"src":"/photos/site/vaghyvel-1200.webp"},{"width":1600,"src":"/photos/site/vaghyvel-1600.webp"},{"width":2000,"src":"/photos/site/vaghyvel-2000.webp"}],"alt":"Väghyvel"}}}}},"om-oss":{"type":"about","hidden":false,"anchor":"om-oss","label":"","heading":"Om oss","link":{"label":"Mer om oss","href":"/om-oss"},"subheading":"Fjärås Sand & Makadam är ett familjeföretag som startades 1961 av Lisa och Olof Gerhardsson.","text":"I dag driver sönerna Lars-Olof och Christer Gerhardsson företaget med hjälp av duktiga anställda. Vi är sju personer – en på kontoret och övriga som chaufförer och maskinförare – med många års erfarenhet av alla förekommande arbeten i branschen.","image":{"src":"/photos/site/entrepenadjobb2-2000.webp","variants":[{"width":480,"src":"/photos/site/entrepenadjobb2-480.webp"},{"width":800,"src":"/photos/site/entrepenadjobb2-800.webp"},{"width":1200,"src":"/photos/site/entrepenadjobb2-1200.webp"},{"width":1600,"src":"/photos/site/entrepenadjobb2-1600.webp"},{"width":2000,"src":"/photos/site/entrepenadjobb2-2000.webp"}],"alt":"Grävmaskin och kranbil på ett jobb"}},"process":{"type":"process","hidden":false,"anchor":"process","label":"","heading":"Så går det till","text":"Från samtalet till materialet på plats.","steps":{"order":["kontakt","offert","tillverkning","leverans"],"items":{"kontakt":{"title":"Kontakt","description":"Ring eller skicka en förfrågan och berätta vad du ska göra och hur mycket du behöver.","icon":"Phone"},"offert":{"title":"Rätt material","description":"Vi hjälper dig välja material och fraktion och räknar ut mängden.","icon":"Ruler"},"tillverkning":{"title":"Lastning","description":"Vi lastar från vår egen täkt – på lastbil eller i storsäck.","icon":"Mountain"},"leverans":{"title":"Leverans","description":"Vi kör ut med lastbil eller kranbil, eller så hämtar du själv i Fjärås.","icon":"Truck"}}}},"faq":{"type":"faq","hidden":false,"anchor":"faq","label":"","heading":"Tips och vanliga frågor","phonePrompt":"Hittar du inte svaret? Ring oss på","items":{"order":["ton","ojamnt","bigbag","hamta","sortiment","moms"],"items":{"ton":{"question":"Hur många kvadratmeter räcker ett ton?","answer":"8–16 mm räcker till ca 23 m² i ett 3 cm tjockt lager, 16–32 mm till ca 14–15 m² i 5 cm och 23–64 mm till ca 9–10 m² i 7 cm. Det gäller dekorytor; till gångar rekommenderar vi 5 cm av 8–16 mm. Använd en padda för att packa materialet."},"ojamnt":{"question":"Mitt underlag är ojämnt – hur gör jag?","answer":"Uppskattningarna gäller en plan yta. Är underlaget ojämnt går det åt mer material. Vi rekommenderar Kross 0–18 för att jämna ut ytan, och sedan önskat material ovanpå."},"bigbag":{"question":"Vad är Big-Bag?","answer":"En storsäck som rymmer ca 1 500 kg. Den lyfts av med kranbil och ställs där du vill. Inget spill, du stör inga grannar och du kan få flera olika material på samma bil, så frakten blir billig."},"hamta":{"question":"Kan jag hämta själv?","answer":"Ja. Ring gärna innan du åker, så att någon är på plats. När du kommer hit kontaktar du kontoret innan du kör in på området, så hjälper vi dig på ett tryggt sätt."},"sortiment":{"question":"Ni har inte det jag söker – vad gör jag?","answer":"Produkterna på sidan är ett urval. Hör av dig, så kan vi ändå ha det i sortimentet."},"moms":{"question":"Ingår moms och frakt i priserna?","answer":"Priser anges exklusive moms och frakt om inget annat står. Frakten beror på var du bor och hur mycket du beställer – vi ger dig ett pris."}}}},"kontakt":{"type":"contact","hidden":false,"anchor":"kontakt","label":"","heading":"Kontakta oss","text":"Berätta vad du ska göra och hur mycket material du behöver, så återkommer vi med pris.","phoneLabel":"Telefon","emailLabel":"E-post","addressLabel":"Besöksadress","openingHoursLabel":"Öppettider","orgLabel":"Org.nr","formHeading":"Begär offert"},"karta":{"type":"map","hidden":false,"anchor":"","label":"","heading":"Hitta till oss","addressPrefix":"Besöksadress:","linkLabel":"Öppna i Google Maps","zoom":13}}}},"om-oss":{"slug":"om-oss","title":"Om oss","seo":{"title":"Om Fjärås Sand & Makadam – familjeföretag sedan 1961","description":"Fjärås Sand & Makadam startades 1961 av Lisa och Olof Gerhardsson och drivs i dag av sönerna Lars-Olof och Christer."},"sections":{"order":["bild","intro","bilder","aret-runt"],"items":{"bild":{"type":"pageHero","hidden":false,"anchor":"","label":"","image":{"src":"/photos/site/20120801-161748-700.webp","variants":[{"width":480,"src":"/photos/site/20120801-161748-480.webp"},{"width":700,"src":"/photos/site/20120801-161748-700.webp"}],"alt":"Täkten i Fjärås"},"size":"tall"},"intro":{"type":"aboutIntro","hidden":false,"anchor":"","label":"","heading":"Om oss","subheading":"Ett familjeföretag som startades 1961 av Lisa och Olof Gerhardsson.","paragraphs":["Fjärås Sand & Makadam krossar och säljer grus, makadam och jordprodukter, som vi levererar med egna lastbilar och kranbil. Vi erbjuder också vägmaterial, harpad matjord, täckbark, barkmull, kullersten och gärdsgårdssten.","I dag driver sönerna Lars-Olof och Christer Gerhardsson företaget med hjälp av duktiga anställda. Totalt är vi sju personer – en på kontoret och övriga som chaufförer och maskinförare.","Tack vare vår egen täkt kan vi erbjuda ett större sortiment av material och fler färger på singel än någon annan i området.","Välkommen att höra av dig – eller kom förbi oss i Fjärås. Ring gärna innan, så att någon är på plats."],"factsTitle":"","facts":{"order":[],"items":{}}},"bilder":{"type":"photoPair","hidden":false,"anchor":"","label":"","photos":{"order":["bild-1","bild-2"],"items":{"bild-1":{"image":{"src":"/photos/site/galleriet2-2000.webp","variants":[{"width":480,"src":"/photos/site/galleriet2-480.webp"},{"width":800,"src":"/photos/site/galleriet2-800.webp"},{"width":1200,"src":"/photos/site/galleriet2-1200.webp"},{"width":1600,"src":"/photos/site/galleriet2-1600.webp"},{"width":2000,"src":"/photos/site/galleriet2-2000.webp"}],"alt":"Hjullastare och lastbilar på grusplanen"}},"bild-2":{"image":{"src":"/photos/site/entrepenadjobb3-2000.webp","variants":[{"width":480,"src":"/photos/site/entrepenadjobb3-480.webp"},{"width":800,"src":"/photos/site/entrepenadjobb3-800.webp"},{"width":1200,"src":"/photos/site/entrepenadjobb3-1200.webp"},{"width":1600,"src":"/photos/site/entrepenadjobb3-1600.webp"},{"width":2000,"src":"/photos/site/entrepenadjobb3-2000.webp"}],"alt":"Grävmaskin på ett dräneringsjobb"}}}}},"aret-runt":{"type":"band","hidden":false,"anchor":"","label":"","heading":"Från täkt till tomt","text":"Vi tar fram materialet i vår egen täkt, krossar det och kör ut det med egna bilar – eller så hämtar du själv.","link":{"label":"Se produkterna","href":"/produkter"},"image":{"src":"/photos/site/hjullastare-1-700.webp","variants":[{"width":480,"src":"/photos/site/hjullastare-1-480.webp"},{"width":700,"src":"/photos/site/hjullastare-1-700.webp"}],"alt":"Hjullastare som lastar en lastbil"},"secondHeading":"Tjänster året runt","secondText":"Grusspridning, väghyvling och dammbindning på sommarhalvåret, snökörning och halkbekämpning på vintern – och transporter, kranbil och maskinflytt hela året.","secondLink":{"label":"Våra tjänster","href":"/#tjanster"}}}}},"aret-runt":{"slug":"produkter","title":"Produkter & priser","seo":{"title":"Produkter och priser – grus, makadam, sand, jord | Fjärås Sand & Makadam","description":"Kross, makadam, naturgrus, sand, stenmjöl, sten, harpad jord, täckbark och barkmull från Fjärås Sand & Makadam."},"sections":{"order":["arbeten","prislista","offert"],"items":{"arbeten":{"type":"uppdragGrid","hidden":false,"anchor":"","label":"","heading":"Produkter & priser","text":"Ett urval av vårt sortiment. Hittar du inte det du söker kan vi ändå ha det – hör av dig. Välj en produkt för bilder i torrt och vått tillstånd.","filterAllLabel":"Alla"},"offert":{"type